param([string]$RagRoot='F:\工作项目\率土之滨\rag', [string]$OfficialFields='C:\Users\fenglei\Downloads\率土之滨_素材集_2026-10-25\_采集记录\cn_hero_data.json', [switch]$SkipImages, [switch]$Resume)
$ErrorActionPreference='Stop'
$root=Split-Path -Parent $PSScriptRoot
$setPath=Join-Path $RagRoot 'imports/s1-cards/s1-cards-1a2b86167f69f57c5d85/卡池与武将数据.json'
$set=Get-Content -Raw -Encoding UTF8 -LiteralPath $setPath|ConvertFrom-Json
$raw=Get-Content -Raw -Encoding UTF8 -LiteralPath $OfficialFields|ConvertFrom-Json
$fields=@{}; foreach($r in $raw){if($fields.ContainsKey([string]$r.id)){throw "Duplicate official card ID: $($r.id)"};$fields[[string]$r.id]=$r}
if(@($set.heroes|Group-Object hero_id|Where-Object Count -gt 1).Count){throw 'Duplicate RAG card identity.'}
$qualityStars=@{'2-UC'=3;'3-R'=4;'4-SR'=5}
$poolDefinitions=@{};foreach($p in $set.pools){$poolDefinitions[[string]$p.id]=$p}
# Only an explicitly documented repeatable recruitment route can support prototype sampling.
# Reward-only, historical, unassigned all-season notices and expired event entries remain archive-only.
$recruitmentTypes=@('天下EX','阵营轮换','赛季初限时','新手活动','活动招募')
function Cs([string]$s){return (ConvertTo-Json -Compress -InputObject $s)}
function Number($s){if(-not $s){return '0'};return ([double]::Parse([string]$s,[Globalization.CultureInfo]::InvariantCulture)).ToString('0.#####',[Globalization.CultureInfo]::InvariantCulture)}
$lines=[Collections.Generic.List[string]]::new()
$lines.Add('// Generated by Tools/Import-S1Rag.ps1 from the pinned local RAG snapshot. Do not hand edit.')
$lines.Add('using System.Collections.Generic; namespace EasternDynasty { public static partial class Catalog { private static IEnumerable<GeneralDefinition> S1Roster() {')
$records=@(); $inbox=Join-Path $root 'AssetInbox/S1Rag'; [IO.Directory]::CreateDirectory($inbox)|Out-Null
$resumeEntries=@{};$skipped=0;$imported=0
if($Resume -and -not $SkipImages){
  . (Join-Path $PSScriptRoot 'Validate-Assets.ps1') -ProjectRoot $root -LibraryOnly
  $resumeValidation=Test-EdAssetManifest (Read-EdAssetManifest $root) $root -CheckFiles
  $resumeEntries=$resumeValidation.Entries
  Write-Output ('RESUME baseline validated: ready='+$resumeValidation.Ready)
}
Add-Type -AssemblyName System.Drawing
foreach($h in $set.heroes){
  $id='s1_'+([string]$h.hero_id -replace '[^a-zA-Z0-9_]','_').ToLowerInvariant(); $r=$fields[[string]$h.hero_id]
  $members=@($set.memberships|Where-Object {$_.hero_id -eq $h.hero_id})
  if($r -and ($r.name -ne $h.name -or $r.country -ne $h.country -or $r.type -ne $h.troop)){throw "Conflicting official card identity: $id"}
  if($r -and ($qualityStars[[string]$r.quality] -ne $h.stars -or $r.methodName -ne $h.skill)){throw "Conflicting official rarity or native skill: $id"}
  $globalRemoved=@($set.changes|Where-Object {$_.hero_id -eq $h.hero_id -and $_.action -eq '全池移除'}).Count -gt 0
  $eligibleMemberships=@($members|Where-Object {
    $m=$_;$p=$poolDefinitions[[string]$m.pool_id]
    $m.status -eq '官方曾确认' -and $p.type -in $recruitmentTypes -and $m.pool_id -ne '名将来投' -and
    -not @($members|Where-Object {$_.pool_id -eq $m.pool_id -and $_.status -eq '已移出此池'}).Count -and
    -not @($set.changes|Where-Object {$_.hero_id -eq $h.hero_id -and $_.pool -eq $m.pool_id -and $_.action -eq '移除'}).Count
  })
  $eligible=($null -ne $r) -and -not $globalRemoved -and $eligibleMemberships.Count -gt 0
  $routes=($eligibleMemberships|ForEach-Object {$_.pool_id}|Sort-Object -Unique)-join '、'
  $evidence=if($eligible){'招募记录：'+$routes+'；仅作试玩池依据，开放条件未复刻'}elseif($globalRemoved){'已有全池移除记录；仅保留历史图鉴'}else{'历史/奖励/待归属档案；不进入试玩招募'}
  $description=[string]$h.unique_name+'。'+$evidence+'。战法名为资料展示，效果尚未逐条实现。'
  $force=if($r){[int][double]$r.attack}else{0}
  $displayFields=', defenseGrowth='+(Number $r.defGrow)+', strategyGrowth='+(Number $r.ruseGrow)+', speedGrowth='+(Number $r.speedGrow)+', siege='+(Number $r.siege)+', siegeGrowth='+(Number $r.siegeGrow)+', attackDistance='+(Number $r.distance)+', biography='+(Cs $r.desc)+', advancedTroops='+(Cs $r.type_availible)+', combination='+(Cs $r.group)+', policyName='+(Cs $r.policyName)+', policyText='+(Cs $r.policyDesc)
  $line='yield return new GeneralDefinition('+ (Cs $id)+','+(Cs $h.name)+',Homeland.Han,'+$h.stars+','+$force+','+(Cs $h.skill)+','+(Cs $description)+'){ s1=true, recruitable='+$eligible.ToString().ToLowerInvariant()+', faction='+(Cs $h.country)+', troop='+(Cs $h.troop)+', sourceUrl='+(Cs $h.official_url)+', evidence='+(Cs $evidence)+', nativeSkill='+(Cs $h.skill)+', nativeSkillText='+(Cs $r.methodDesc)+', defense='+(Number $r.def)+', strategy='+(Number $r.ruse)+', speed='+(Number $r.speed)+', cost='+(Number $r.cost)+', attackGrowth='+(Number $r.attGrow)+' };'
  $line=$line.Substring(0,$line.Length-3)+$displayFields+' };'
  $lines.Add($line)
  $a=$set.assets|Where-Object {$_.asset_id -eq ('art_'+$h.hero_id)}|Select-Object -First 1
  if($a -and $a.hero_id -ne $h.hero_id){throw "Portrait identity does not match card: $id"}
  $assessments=@(foreach($m in $members){
    $p=$poolDefinitions[[string]$m.pool_id]
    $routeAllowed=($eligibleMemberships -contains $m) -and -not $globalRemoved -and ($null-ne$r)
    $reason=if($globalRemoved){'已有全池移除记录'}elseif($null-eq$r){'缺少可唯一匹配的官方属性'}elseif($routeAllowed){'明确官方招募关系；原版开放条件未复刻'}elseif($m.status-eq'已移出此池' -or @($set.changes|Where-Object {$_.hero_id-eq$h.hero_id-and$_.pool-eq$m.pool_id-and$_.action-eq'移除'}).Count){'已有明确同池移除记录'}elseif($p.type-eq'取得途径'){'奖励取得不等于可重复随机招募'}elseif($p.type-eq'历史限时活动'){'活动已结束，保留历史资料'}elseif($p.type-eq'待核实'){'全赛季/历史资料尚未核实当前S1具体招募池'}elseif($m.pool_id-eq'名将来投'){'新手任务取得，未证明为可重复招募池'}elseif($p.type-notin$recruitmentTypes){'历史或未支持的取得类别'}else{'成员证据不足以进入原型取证池：'+$m.status}
    [pscustomobject]@{poolId=$m.pool_id;poolType=$p.type;status=$m.status;sourceIds=$m.source_id;originalOpeningCondition=$p.opening_condition;eligible=$routeAllowed;reason=$reason}
  })
  $records+= [pscustomobject]@{id=$id;sourceHeroId=$h.hero_id;faction=$h.country;stars=$h.stars;eligible=$eligible;scope=$h.scope;memberships=$members;eligibleRecruitmentMemberships=$eligibleMemberships;routeAssessments=$assessments;globallyRemoved=$globalRemoved;asset=$a;officialFieldsAvailable=($null-ne$r)}
  if(-not $SkipImages){
    if(-not $a){throw "Missing art record: $id"}
    $source=Get-ChildItem -LiteralPath (Join-Path $RagRoot ('assets/'+$a.sha256.Substring(0,2))) -Filter ($a.sha256+'.*')|Select-Object -First 1
    if(-not $source -or (Get-FileHash -LiteralPath $source.FullName -Algorithm SHA256).Hash.ToLowerInvariant() -ne $a.sha256){throw "RAG image hash mismatch: $id"}
    $expectedPurpose=$h.unique_name+' 官网裁切立绘'
    $registered=$resumeEntries['portrait.'+$id]
    $skipRegistered=$false
    if($Resume -and $registered -and $registered.status -eq 'ready' -and $registered.kind -eq 'portrait' -and $registered.purpose -ceq $expectedPurpose -and $registered.source.kind -eq 'user-provided' -and $registered.source.reference -and $registered.source.reference.Contains('RAG SHA256='+$a.sha256)){
      $registeredPath=Get-EdAssetPath $root $registered.resourcePath
      Assert-EdAssetNoReparse $registeredPath
      $skipRegistered=(Test-Path -LiteralPath $registeredPath -PathType Leaf) -and (Get-FileHash -LiteralPath $registeredPath -Algorithm SHA256).Hash.ToLowerInvariant() -ceq $registered.sha256
    }
    if($skipRegistered){$skipped++;continue}
    $png=Join-Path $inbox ($id+'.png')
    # Lossless re-encoding of decoded source pixels only: no crop, repaint, resizing or invented art.
    $bitmap=[Drawing.Bitmap]::new($source.FullName); try{$bitmap.Save($png,[Drawing.Imaging.ImageFormat]::Png)}finally{$bitmap.Dispose()}
    & (Join-Path $PSScriptRoot 'Import-Asset.ps1') -Id ('portrait.'+$id) -Kind portrait -SourcePath $png -Purpose ($h.unique_name+' 官网裁切立绘') -SourceKind user-provided -SourceReference ($a.image_url+' | RAG SHA256='+$a.sha256+' | JPEG decoded pixels losslessly stored as PNG') -Rights '用户指定本地RAG资料；网易原始美术；此记录不授予商业再分发许可。' -CreatedUtc '2026-10-25' -Replace | Out-Null
    $imported++;if($imported%10 -eq 0){Write-Output ('S1 image progress: imported='+$imported+'; verified skips='+$skipped+'; examined='+$records.Count+'/'+$set.heroes.Count)}
  }
}
$lines.Add('} } }')
[IO.File]::WriteAllLines((Join-Path $root 'Assets/EasternDynasty/Scripts/Core/S1Roster.Generated.cs'),$lines,[Text.UTF8Encoding]::new($false))
$report=[pscustomobject]@{snapshot='s1-cards-1a2b86167f69f57c5d85';sourceSha256=(Get-FileHash $setPath -Algorithm SHA256).Hash.ToLowerInvariant();officialFieldsSha256=(Get-FileHash $OfficialFields -Algorithm SHA256).Hash.ToLowerInvariant();asOf=$set.as_of;coverage=$set.coverage;eligibilityPolicy='Official membership in an actual recruitment category; exclude reward-only, historical, expired event, unassigned all-season and removed routes. This is prototype sampling, not a complete current S1 pool or unlock-timing implementation.';limitations=$set.limitations;records=$records}
[IO.File]::WriteAllText((Join-Path $root 'Docs/S1-Rag-Snapshot.json'),($report|ConvertTo-Json -Depth 15),[Text.UTF8Encoding]::new($false))
Write-Output ('S1_RAG_IMPORT_OK: cards='+$records.Count+'; prototype-recruitable='+@($records|Where-Object eligible).Count+'; historical catalog only='+@($records|Where-Object {-not $_.eligible}).Count)
if(-not $SkipImages){Write-Output ('S1_IMAGES: imported='+$imported+'; verified skips='+$skipped)}
